//! FIR's C API: the builder, verifier, printer, and interpreter of the `fir` crate behind
//! `extern "C"` functions, opaque handles, and 32-bit ids. The header is
//! `include/fir.h`, generated by cbindgen from this crate (a test keeps it current); link
//! `libfir_capi.a` (or the shared library) and, on Linux, `-lpthread -ldl -lm`.
//!
//! ```c
//! #include "fir.h"
//!
//! FirModule *m = fir_module_new();
//! FirType i32 = fir_type_int(32);
//! FirFunc f = fir_func_declare(m, "inc", &i32, 1, &i32, 1);
//! FirBuilder *b = fir_func_begin(m, f);
//! FirValue x = fir_builder_param(b, 0);
//! FirValue one = fir_int_const(b, i32, 1);
//! FirValue y = fir_int_arith(b, FIR_ARITH_OP_ADD, FIR_OVF_NSW, x, one);
//! fir_func_ret(b, &y, 1);
//! if (fir_func_end(b) != FIR_OK || fir_module_verify(m) != FIR_OK)
//!     fprintf(stderr, "%s\n", fir_module_error(m));
//! const char *args[] = {"41"};
//! char *out;
//! if (fir_module_run(m, "inc", args, 1, FIR_DEFAULT_FUEL, &out) == FIR_OK) {
//!     puts(out);                     // returned i32 42
//!     fir_string_free(out);
//! }
//! fir_module_free(m);
//! ```
//!
//! **Handles and ids.** A `FirModule` is a module being built; it owns everything made in it.
//! A `FirBuilder` builds one function of a module, from `fir_func_begin` to `fir_func_end`;
//! a module builds one function at a time. Everything else is a 32-bit id: types (`FirType`),
//! functions (`FirFunc`), globals (`FirGlobal`), and initializers (`FirInit`) of a module, and
//! values (`FirValue`, which also stands for holes), ops (`FirOp`), and regions (`FirRegion`,
//! which also stands for blocks of `cf.blocks`) of the function being built. `FIR_INVALID` is
//! no id. Value types are ids made without a module: `fir_type_int(32)`, `fir_type_byte(8)`,
//! `FIR_TYPE_PTR`.
//!
//! **Ops.** One function per op, generated from its declaration (`src/generated/ops.rs`), named
//! like the Rust builder's methods with `fir_` in front: its arguments are the builder, the
//! result types the op can't imply, every modifier (a `FIR_OVF_*`, `FIR_EDGE_*`, … constant:
//! none has a default), then the op's immediates and operands as its text writes them; lists are
//! a pointer and a length. Ops with regions are made with their regions empty
//! (`fir_cf_if_begin`); `fir_op_region` and `fir_position_at_end` fill them, and
//! `fir_block_new` adds the blocks of `cf.blocks`.
//!
//! **Errors.** No Rust panic crosses the boundary. A call that fails returns `FIR_INVALID`, a
//! null pointer, or a `FirStatus` other than `FIR_OK`, adds nothing to the module, and leaves a
//! message that `fir_module_error` returns. Bad ids and enum values are reported, not trusted.
//! Pointers must be valid, and lists as long as their lengths say.
//!
//! **Ownership.** The caller frees what it gets from a `_new`, `_parse`, or `_begin` function
//! and every `char *` returned: `fir_module_free`, `fir_func_end` or `fir_func_abandon` (which
//! free the builder), and `fir_string_free`. A builder must not outlive its module. The string
//! from `fir_module_error` belongs to the module and lasts until its next failed call. Pointers
//! passed in are only read during the call. A module and its builder are used from one thread
//! at a time.
//!
//! **Stability.** The functions, structs, constants, and their values are versioned by
//! `FIR_API_VERSION`: a release only adds to them (a minor version), and anything removed or
//! changed bumps the major version. Op functions follow the op table, which is versioned the
//! same way.

#![allow(clippy::missing_safety_doc)]

use std::ffi::{CStr, CString, c_char};
use std::panic::{AssertUnwindSafe, catch_unwind};

use fir::{
    AllocFail, ArithOp, BitOp, BuildError, DivOp, Edge, ExtEffect, FactArg, FuncBuilder, FuncRef,
    GlobalRef, Init, IntImm, MemClass, ModuleBuilder, OpId, Operand, Ovf, Policy, Pred, RegionId,
    ShiftEdge, ShiftOp, SpaceCfg, SwitchCase, Target, TruncMode, Trust, Ty, TyId, ValueDef,
};

#[path = "generated/ops.rs"]
#[rustfmt::skip]
mod ops;
pub use ops::*;

/// The API's version: the major version times 65536, plus the minor version.
pub const FIR_API_VERSION: u32 = 1 << 16;

/// No id: what a call returns when it fails.
pub const FIR_INVALID: u32 = u32::MAX;

/// The interpreter's default step limit, as `fir run` uses.
pub const FIR_DEFAULT_FUEL: u64 = 1_000_000;

/// A value or a hole of the function being built.
pub type FirValue = u32;
/// An op of the function being built.
pub type FirOp = u32;
/// A region of the function being built; also a block of `cf.blocks`.
pub type FirRegion = u32;
/// A type: a value type (`fir_type_int`, `fir_type_byte`, `FIR_TYPE_PTR`), or a struct, array,
/// or function type of a module.
pub type FirType = u32;
/// A function of a module, defined in it or external.
pub type FirFunc = u32;
/// A global of a module.
pub type FirGlobal = u32;
/// A global's initializer, made in a module for `fir_global_declare`.
pub type FirInit = u32;

/// What a call that doesn't return an id reports.
pub type FirStatus = u32;
pub const FIR_OK: FirStatus = 0;
/// An argument names nothing, breaks the op's typing rule, or clashes with a declaration.
pub const FIR_ERR_INVALID: FirStatus = 1;
/// The module doesn't verify.
pub const FIR_ERR_VERIFY: FirStatus = 2;
/// The text doesn't parse.
pub const FIR_ERR_PARSE: FirStatus = 3;
/// A run can't start: no such function, or bad arguments.
pub const FIR_ERR_RUN: FirStatus = 4;
/// A bug in FIR, caught before it crossed the boundary.
pub const FIR_ERR_INTERNAL: FirStatus = 5;

/// `ptr`
pub const FIR_TYPE_PTR: FirType = 0xC000_0000;
const TY_TAG: u32 = 3 << 30;
const TY_BYTE: u32 = 1 << 30;
const TY_AGG: u32 = 2 << 30;

/// A branch target: a block, and the arguments for its parameters.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct FirTarget {
    pub block: FirRegion,
    pub args: *const FirValue,
    pub nargs: usize,
}

/// One case of `cf.switch`.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct FirCase {
    pub key: i64,
    pub target: FirTarget,
}

/// One entry of a data layout's integer alignments.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct FirIntAlign {
    /// In bits.
    pub width: u32,
    /// In bytes.
    pub align: u32,
}

/// A fact on a value: a `FIR_FACT_*` kind, a `FIR_TRUST_*` tag, and its numbers (the bounds of a
/// range; `lo` is the alignment of `FIR_FACT_ALIGN`).
#[repr(C)]
#[derive(Clone, Copy)]
pub struct FirFact {
    pub kind: FirFactKind,
    pub trust: FirTrust,
    pub lo: i64,
    pub hi: i64,
}

