/// A C enum's value as the Rust value it stands for.
pub(crate) trait CEnum: Sized {
    fn from_c(x: u32) -> Result<Self, BuildError>;
}

macro_rules! c_enum {
    ($t:ty, $name:literal: $($c:ident => $v:expr),* $(,)?) => {
        impl CEnum for $t {
            fn from_c(x: u32) -> Result<$t, BuildError> {
                match x {
                    $($c => Ok($v),)*
                    _ => Err(BuildError::new(format!("{x} is not a {}", $name))),
                }
            }
        }
    };
}

c_enum!(Ovf, "FirOvf":
    FIR_OVF_WRAP => Ovf::Wrap, FIR_OVF_NSW => Ovf::Nsw, FIR_OVF_NUW => Ovf::Nuw,
    FIR_OVF_NSW_NUW => Ovf::NswNuw, FIR_OVF_S_TRAP => Ovf::Trap(true),
    FIR_OVF_U_TRAP => Ovf::Trap(false), FIR_OVF_S_SAT => Ovf::Sat(true),
    FIR_OVF_U_SAT => Ovf::Sat(false), FIR_OVF_S_UB => Ovf::Ub(true), FIR_OVF_U_UB => Ovf::Ub(false));
c_enum!(Edge, "FirEdge":
    FIR_EDGE_UB => Edge::Ub, FIR_EDGE_TRAP => Edge::Trap, FIR_EDGE_TOTAL => Edge::Total,
    FIR_EDGE_WRAP => Edge::Wrap);
c_enum!(ShiftEdge, "FirShiftEdge":
    FIR_SHIFT_EDGE_UB => ShiftEdge::Ub, FIR_SHIFT_EDGE_TRAP => ShiftEdge::Trap,
    FIR_SHIFT_EDGE_MASK => ShiftEdge::Mask, FIR_SHIFT_EDGE_TOTAL => ShiftEdge::Total);
c_enum!(TruncMode, "FirTruncMode":
    FIR_TRUNC_MODE_WRAP => TruncMode::Wrap, FIR_TRUNC_MODE_NSW => TruncMode::Nsw,
    FIR_TRUNC_MODE_NUW => TruncMode::Nuw);
c_enum!(Pred, "FirPred":
    FIR_PRED_EQ => Pred::Eq, FIR_PRED_NE => Pred::Ne, FIR_PRED_SLT => Pred::Slt,
    FIR_PRED_SLE => Pred::Sle, FIR_PRED_SGT => Pred::Sgt, FIR_PRED_SGE => Pred::Sge,
    FIR_PRED_ULT => Pred::Ult, FIR_PRED_ULE => Pred::Ule, FIR_PRED_UGT => Pred::Ugt,
    FIR_PRED_UGE => Pred::Uge);
c_enum!(ArithOp, "FirArithOp":
    FIR_ARITH_OP_ADD => ArithOp::Add, FIR_ARITH_OP_SUB => ArithOp::Sub,
    FIR_ARITH_OP_MUL => ArithOp::Mul);
c_enum!(BitOp, "FirBitOp":
    FIR_BIT_OP_AND => BitOp::And, FIR_BIT_OP_OR => BitOp::Or, FIR_BIT_OP_XOR => BitOp::Xor);
c_enum!(DivOp, "FirDivOp":
    FIR_DIV_OP_DIV_S => DivOp::DivS, FIR_DIV_OP_DIV_U => DivOp::DivU,
    FIR_DIV_OP_REM_S => DivOp::RemS, FIR_DIV_OP_REM_U => DivOp::RemU);
c_enum!(ShiftOp, "FirShiftOp":
    FIR_SHIFT_OP_SHL => ShiftOp::Shl, FIR_SHIFT_OP_SHR_U => ShiftOp::ShrU,
    FIR_SHIFT_OP_SHR_S => ShiftOp::ShrS);
c_enum!(AllocFail, "FirAllocFail":
    FIR_ALLOC_FAIL_NULL => AllocFail::Null, FIR_ALLOC_FAIL_TRAP => AllocFail::Trap);
c_enum!(Policy, "FirPolicy":
    FIR_POLICY_C => Policy::C, FIR_POLICY_PACKED => Policy::Packed,
    FIR_POLICY_AUTO => Policy::Auto);
c_enum!(Trust, "FirTrust":
    FIR_TRUST_ASSUME => Trust::Assume, FIR_TRUST_CHECK => Trust::Check,
    FIR_TRUST_PROVED => Trust::Proved);
c_enum!(ExtEffect, "FirEffect":
    FIR_EFFECT_READ_ARGS => ExtEffect::Read(MemClass::Args),
    FIR_EFFECT_READ_EXPOSED => ExtEffect::Read(MemClass::Exposed),
    FIR_EFFECT_READ_GLOBALS => ExtEffect::Read(MemClass::Globals),
    FIR_EFFECT_WRITE_ARGS => ExtEffect::Write(MemClass::Args),
    FIR_EFFECT_WRITE_EXPOSED => ExtEffect::Write(MemClass::Exposed),
    FIR_EFFECT_WRITE_GLOBALS => ExtEffect::Write(MemClass::Globals),
    FIR_EFFECT_ALLOC => ExtEffect::Alloc, FIR_EFFECT_FREE => ExtEffect::Free,
    FIR_EFFECT_TRAP => ExtEffect::Trap, FIR_EFFECT_DIVERGE => ExtEffect::Diverge,
    FIR_EFFECT_UNWIND => ExtEffect::Unwind);

// Handles.

/// A module being built, with everything made in it.
pub struct FirModule {
    mb: ModuleBuilder,
    inits: Vec<Init>,
    error: CString,
}

/// Builds one function of a module.
pub struct FirBuilder {
    module: *mut FirModule,
}

/// Why a call failed.
struct Fail {
    status: FirStatus,
    msg: String,
}

impl From<BuildError> for Fail {
    fn from(e: BuildError) -> Fail {
        Fail {
            status: FIR_ERR_INVALID,
            msg: e.message().to_owned(),
        }
    }
}

fn fail<T>(status: FirStatus, msg: impl Into<String>) -> Result<T, Fail> {
    Err(Fail {
        status,
        msg: msg.into(),
    })
}

fn c_string(s: String) -> CString {
    CString::new(s).unwrap_or_else(|e| {
        let mut bytes = e.into_vec();
        bytes.retain(|&b| b != 0);
        CString::new(bytes).expect("no NUL left")
    })
}

fn panic_message(p: &(dyn std::any::Any + Send)) -> String {
    let what = p
        .downcast_ref::<&str>()
        .map(|s| s.to_string())
        .or_else(|| p.downcast_ref::<String>().cloned())
        .unwrap_or_default();
    format!("internal error: {what}")
}

/// Run `f` on a module, catching panics. On failure, the module keeps the message and the call
/// returns `invalid`, or the failure's status when `status` is set.
unsafe fn with_module<T>(
    m: *mut FirModule,
    invalid: T,
    status: impl FnOnce(FirStatus) -> Option<T>,
    f: impl FnOnce(&mut FirModule) -> Result<T, Fail>,
) -> T {
    let Some(m) = (unsafe { m.as_mut() }) else {
        return status(FIR_ERR_INVALID).unwrap_or(invalid);
    };
    let out = catch_unwind(AssertUnwindSafe(|| f(&mut *m)));
    let e = match out {
        Ok(Ok(v)) => return v,
        Ok(Err(e)) => e,
        Err(p) => Fail {
            status: FIR_ERR_INTERNAL,
            msg: panic_message(&*p),
        },
    };
    m.error = c_string(e.msg);
    status(e.status).unwrap_or(invalid)
}

/// [`with_module`] for a call returning an id or a pointer (`invalid` on failure).
unsafe fn module_id<T>(
    m: *mut FirModule,
    invalid: T,
    f: impl FnOnce(&mut FirModule) -> Result<T, Fail>,
) -> T {
    unsafe { with_module(m, invalid, |_| None, f) }
}

/// [`with_module`] for a call returning a status.
unsafe fn module_status(
    m: *mut FirModule,
    f: impl FnOnce(&mut FirModule) -> Result<(), Fail>,
) -> FirStatus {
    unsafe { with_module(m, FIR_OK, Some, |m| f(m).map(|()| FIR_OK)) }
}

/// Run `f` on the function a builder builds; see [`with_module`].
pub(crate) unsafe fn with_builder<T>(
    fb: *mut FirBuilder,
    invalid: T,
    f: impl FnOnce(&mut FuncBuilder<'_>) -> Result<T, BuildError>,
) -> T {
    let Some(b) = (unsafe { fb.as_ref() }) else {
        return invalid;
    };
    unsafe {
        module_id(b.module, invalid, |m| match m.mb.current() {
            Some(mut fb) => Ok(f(&mut fb)?),
            None => fail(FIR_ERR_INVALID, "no function is being built"),
        })
    }
}

unsafe fn builder_status(
    fb: *mut FirBuilder,
    f: impl FnOnce(&mut FuncBuilder<'_>) -> Result<(), BuildError>,
) -> FirStatus {
    let Some(b) = (unsafe { fb.as_ref() }) else {
        return FIR_ERR_INVALID;
    };
    unsafe {
        module_status(b.module, |m| match m.mb.current() {
            Some(mut fb) => Ok(f(&mut fb)?),
            None => fail(FIR_ERR_INVALID, "no function is being built"),
        })
    }
}

// Conversions for the generated functions.

/// A list passed from C; empty when the length is 0, whatever the pointer.
pub(crate) unsafe fn list<'a, T>(p: *const T, n: usize) -> &'a [T] {
    if n == 0 || p.is_null() {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(p, n) }
    }
}

/// Operands passed from C: a `FirValue` is an operand's 32 bits.
pub(crate) unsafe fn values<'a>(p: *const FirValue, n: usize) -> &'a [Operand] {
    // `Operand` is `repr(transparent)` over `u32`, and every `u32` is an operand (one that names
    // nothing is rejected when used).
    unsafe { list(p.cast::<Operand>(), n) }
}

pub(crate) fn ty(t: FirType) -> Result<Ty, BuildError> {
    let n = t & !TY_TAG;
    Ok(match t & TY_TAG {
        0 => Ty::Int(n),
        TY_BYTE => Ty::Byte(n),
        TY_AGG => Ty::Agg(TyId::from_raw(n)),
        _ if t == FIR_TYPE_PTR => Ty::Ptr,
        _ => return Err(BuildError::new(format!("{t:#x} is not a type"))),
    })
}

fn ty_to_c(t: Ty) -> FirType {
    match t {
        Ty::Int(w) => w,
        Ty::Byte(w) => TY_BYTE | w,
        Ty::Agg(id) => TY_AGG | id.raw(),
        Ty::Ptr => FIR_TYPE_PTR,
    }
}

pub(crate) unsafe fn tys(p: *const FirType, n: usize) -> Result<Vec<Ty>, BuildError> {
    unsafe { list(p, n) }.iter().map(|&t| ty(t)).collect()
}

pub(crate) unsafe fn cstr<'a>(p: *const c_char) -> Result<&'a str, BuildError> {
    if p.is_null() {
        return Err(BuildError::new("a name is missing"));
    }
    unsafe { CStr::from_ptr(p) }
        .to_str()
        .map_err(|_| BuildError::new("a name is not UTF-8"))
}

pub(crate) fn target(t: FirTarget, args: &[Operand]) -> Target<'_> {
    Target::new(RegionId::from_raw(t.block), args)
}

pub(crate) unsafe fn switch_cases<'a>(p: *const FirCase, n: usize) -> Vec<SwitchCase<'a>> {
    unsafe { list(p, n) }
        .iter()
        .map(|c| SwitchCase {
            key: c.key.into(),
            target: target(c.target, unsafe { values(c.target.args, c.target.nargs) }),
        })
        .collect()
}

// Modules.

/// The API version the library was built with: `FIR_API_VERSION`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_api_version() -> u32 {
    FIR_API_VERSION
}

/// A new, empty module. Free it with `fir_module_free`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_module_new() -> *mut FirModule {
    Box::into_raw(Box::new(FirModule {
        mb: ModuleBuilder::new(),
        inits: Vec::new(),
        error: CString::default(),
    }))
}

/// Parse FIR text into a new module (`*out`), to verify, print, run, or add to. On failure,
/// `*error` gets the message, which the caller frees with `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_parse(
    text: *const c_char,
    out: *mut *mut FirModule,
    error: *mut *mut c_char,
) -> FirStatus {
    let r = catch_unwind(|| -> Result<ModuleBuilder, (FirStatus, String)> {
        let text = unsafe { cstr(text) }.map_err(|e| (FIR_ERR_INVALID, e.to_string()))?;
        let m = fir::parse_module(text).map_err(|e| (FIR_ERR_PARSE, e))?;
        ModuleBuilder::from_module(m).map_err(|e| (FIR_ERR_INVALID, e.to_string()))
    })
    .unwrap_or_else(|p| Err((FIR_ERR_INTERNAL, panic_message(&*p))));
    match r {
        Ok(mb) => {
            if let Some(out) = unsafe { out.as_mut() } {
                *out = Box::into_raw(Box::new(FirModule {
                    mb,
                    inits: Vec::new(),
                    error: CString::default(),
                }));
            }
            FIR_OK
        }
        Err((status, msg)) => {
            if let Some(error) = unsafe { error.as_mut() } {
                *error = c_string(msg).into_raw();
            }
            status
        }
    }
}

/// Free a module and everything in it. A builder of it can't be used afterwards.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_free(m: *mut FirModule) {
    if !m.is_null() {
        drop(unsafe { Box::from_raw(m) });
    }
}

/// The message of the module's last failed call (empty if none failed). It belongs to the
/// module, and lasts until its next failed call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_error(m: *const FirModule) -> *const c_char {
    match unsafe { m.as_ref() } {
        Some(m) => m.error.as_ptr(),
        None => c"no module".as_ptr(),
    }
}

/// Free a string FIR returned.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_string_free(s: *mut c_char) {
    if !s.is_null() {
        drop(unsafe { CString::from_raw(s) });
    }
}

/// Set the default memory space's data layout: pointer and address sizes in bits, the pointer
/// alignment in bytes (0: the natural one), and the integer alignments by increasing width (none:
/// the default ones). Set it before building functions.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_set_space(
    m: *mut FirModule,
    ptr_bits: u32,
    addr_bits: u32,
    ptr_align: u32,
    ints: *const FirIntAlign,
    nints: usize,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let mut sp = SpaceCfg {
                ptr_bits,
                addr_bits,
                ptr_align: if ptr_align == 0 {
                    SpaceCfg::natural_align(ptr_bits)
                } else {
                    ptr_align
                },
                ..SpaceCfg::default()
            };
            if nints > 0 {
                sp.ints = list(ints, nints)
                    .iter()
                    .map(|e| (e.width, e.align))
                    .collect();
            }
            m.mb.set_space(sp);
            Ok(())
        })
    }
}

/// Check the module (its finished functions) as `fir check` does. On failure the message is the
/// verifier's.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_verify(m: *mut FirModule) -> FirStatus {
    unsafe {
        module_status(m, |m| match fir::verify_module(m.mb.module()) {
            Ok(_) => Ok(()),
            Err(e) => fail(FIR_ERR_VERIFY, e),
        })
    }
}

/// The module (its finished functions) in canonical text, with locations or without. Free it with
/// `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_print(m: *mut FirModule, show_locs: bool) -> *mut c_char {
    unsafe {
        module_id(m, std::ptr::null_mut(), |m| {
            Ok(c_string(m.mb.module().render(show_locs)).into_raw())
        })
    }
}

/// Verify the module, then run `@name` with arguments written as text (integers, `null`,
/// `poison`) for at most `fuel` steps. `*out` gets the outcome in one line, as `fir run` prints
/// it (`returned i32 3`, `ub div0 @4:3`, …); free it with `fir_string_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_module_run(
    m: *mut FirModule,
    name: *const c_char,
    args: *const *const c_char,
    nargs: usize,
    fuel: u64,
    out: *mut *mut c_char,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let name = cstr(name)?;
            let args = list(args, nargs)
                .iter()
                .map(|&a| cstr(a))
                .collect::<Result<Vec<_>, _>>()?;
            let module = m.mb.module();
            if let Err(e) = fir::verify_module(module) {
                return fail(FIR_ERR_VERIFY, e);
            }
            match fir::interp::run(module, name, &args, fuel) {
                Ok(line) => {
                    if let Some(out) = out.as_mut() {
                        *out = c_string(line).into_raw();
                    }
                    Ok(())
                }
                Err(e) => fail(FIR_ERR_RUN, e),
            }
        })
    }
}

// Types.

/// `iN`, for `1 <= width < 2^30`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_type_int(width: u32) -> FirType {
    if width == 0 || width & TY_TAG != 0 {
        FIR_INVALID
    } else {
        width
    }
}

/// `bN`, for `1 <= width < 2^30`.
#[unsafe(no_mangle)]
pub extern "C" fn fir_type_byte(width: u32) -> FirType {
    if width == 0 || width & TY_TAG != 0 {
        FIR_INVALID
    } else {
        TY_BYTE | width
    }
}

/// `struct<policy>{fields}`
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_struct(
    m: *mut FirModule,
    policy: FirPolicy,
    fields: *const FirType,
    nfields: usize,
) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let fields = tys(fields, nfields)?;
            Ok(ty_to_c(m.mb.struct_ty(Policy::from_c(policy)?, &fields)?))
        })
    }
}

/// `array<n x elem>`
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_array(m: *mut FirModule, n: u64, elem: FirType) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            Ok(ty_to_c(m.mb.array_ty(n, ty(elem)?)?))
        })
    }
}

/// `func<(params) -> rets>`, the signature of `func.call.indirect`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_type_func(
    m: *mut FirModule,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
) -> FirType {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            Ok(ty_to_c(m.mb.func_ty(&ps, &rs)?))
        })
    }
}

// Declarations.

/// Declare a function `@name(params) -> rets`, to call it or take its address, and define it
/// with `fir_func_begin`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_declare(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            Ok(m.mb.declare_func(cstr(name)?, &ps, &rs)?.raw())
        })
    }
}

/// The function or external function named `name`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_find(m: *mut FirModule, name: *const c_char) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let name = cstr(name)?;
            match m.mb.func_ref(name) {
                Some(f) => Ok(f.raw()),
                None => fail(FIR_ERR_INVALID, format!("no function @{name}")),
            }
        })
    }
}

/// `extern func @name(params) -> rets effects[…] trust`: a function outside the module, with the
/// `FIR_EFFECT_*` it may have.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_extern_declare(
    m: *mut FirModule,
    name: *const c_char,
    params: *const FirType,
    nparams: usize,
    rets: *const FirType,
    nrets: usize,
    effects: *const FirEffect,
    neffects: usize,
    trust: FirTrust,
) -> FirFunc {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let (ps, rs) = (tys(params, nparams)?, tys(rets, nrets)?);
            let es = list(effects, neffects)
                .iter()
                .map(|&e| ExtEffect::from_c(e))
                .collect::<Result<Vec<_>, _>>()?;
            let f =
                m.mb.extern_func(cstr(name)?, &ps, &rs, &es, Trust::from_c(trust)?)?;
            Ok(f.raw())
        })
    }
}

/// `global [const] @name: ty [align align] = init`. An initializer that takes the address of a
/// global declared later is set afterwards with `fir_global_set_init`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_global_declare(
    m: *mut FirModule,
    name: *const c_char,
    ty_: FirType,
    constant: bool,
    align: u32,
    init: FirInit,
) -> FirGlobal {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.init(init)?;
            let g = m.mb.global(cstr(name)?, ty(ty_)?, constant, align, init)?;
            Ok(g.raw())
        })
    }
}

/// Replace a global's initializer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_global_set_init(
    m: *mut FirModule,
    g: FirGlobal,
    init: FirInit,
) -> FirStatus {
    unsafe {
        module_status(m, |m| {
            let init = m.init(init)?;
            Ok(m.mb.set_global_init(GlobalRef::from_raw(g), init)?)
        })
    }
}

impl FirModule {
    fn init(&self, i: FirInit) -> Result<Init, BuildError> {
        match self.inits.get(i as usize) {
            Some(&init) => Ok(init),
            None => Err(BuildError::new(format!("initializer {i} does not exist"))),
        }
    }

    fn add_init(&mut self, init: Init) -> FirInit {
        self.inits.push(init);
        (self.inits.len() - 1) as FirInit
    }
}

/// `zero`: every byte zero.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_zero(m: *mut FirModule) -> FirInit {
    unsafe { module_id(m, FIR_INVALID, |m| Ok(m.add_init(Init::Zero))) }
}

/// `null`
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_null(m: *mut FirModule) -> FirInit {
    unsafe { module_id(m, FIR_INVALID, |m| Ok(m.add_init(Init::Null))) }
}

/// An integer, for an `iN` or `bN`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_int(m: *mut FirModule, n: i64) -> FirInit {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.mb.init_int(n);
            Ok(m.add_init(init))
        })
    }
}

/// `bytes "…"`: the whole object's bytes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_bytes(m: *mut FirModule, bytes: *const u8, n: usize) -> FirInit {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.mb.init_bytes(list(bytes, n));
            Ok(m.add_init(init))
        })
    }
}

/// `@f`: a function's address.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_func(m: *mut FirModule, f: FirFunc) -> FirInit {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.mb.init_func(FuncRef::from_raw(f))?;
            Ok(m.add_init(init))
        })
    }
}

/// `@g`: a global's address.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_global(m: *mut FirModule, g: FirGlobal) -> FirInit {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let init = m.mb.init_global(GlobalRef::from_raw(g))?;
            Ok(m.add_init(init))
        })
    }
}

/// `{…}`: one initializer per struct field or array element.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_init_list(
    m: *mut FirModule,
    items: *const FirInit,
    n: usize,
) -> FirInit {
    unsafe {
        module_id(m, FIR_INVALID, |m| {
            let items = list(items, n)
                .iter()
                .map(|&i| m.init(i))
                .collect::<Result<Vec<_>, _>>()?;
            let init = m.mb.init_list(&items);
            Ok(m.add_init(init))
        })
    }
}

// Building functions.

/// Start building a declared function, at the end of its entry region. Finish with
/// `fir_func_end` (or drop it with `fir_func_abandon`), which frees the builder. Null on failure.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_begin(m: *mut FirModule, f: FirFunc) -> *mut FirBuilder {
    unsafe {
        module_id(m, std::ptr::null_mut(), |mm| {
            mm.mb.define(FuncRef::from_raw(f))?;
            Ok(Box::into_raw(Box::new(FirBuilder { module: m })))
        })
    }
}

/// Finish the function and add it to the module; free the builder, whatever the outcome.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_end(fb: *mut FirBuilder) -> FirStatus {
    if fb.is_null() {
        return FIR_ERR_INVALID;
    }
    let b = unsafe { Box::from_raw(fb) };
    unsafe {
        module_status(b.module, |m| match m.mb.current() {
            Some(f) => Ok(f.finish().map(drop)?),
            None => fail(FIR_ERR_INVALID, "no function is being built"),
        })
    }
}

/// Drop the function being built (it stays declared) and free the builder.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_func_abandon(fb: *mut FirBuilder) {
    if fb.is_null() {
        return;
    }
    let b = unsafe { Box::from_raw(fb) };
    unsafe {
        module_status(b.module, |m| {
            m.mb.abandon_func();
            Ok(())
        });
    }
}

/// Parameter `i` of the function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_builder_param(fb: *mut FirBuilder, i: u32) -> FirValue {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let ps = f.params();
            if (i as usize) < ps.len() {
                Ok(ps.get(i as usize).raw())
            } else {
                Err(BuildError::new(format!(
                    "the function has no parameter {i}"
                )))
            }
        })
    }
}

/// The function's entry region.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_builder_entry(fb: *mut FirBuilder) -> FirRegion {
    unsafe { with_builder(fb, FIR_INVALID, |f| Ok(f.entry().raw())) }
}

/// Result `i` of an op.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_op_result(fb: *mut FirBuilder, op: FirOp, i: u32) -> FirValue {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let rs = f.results(OpId::from_raw(op))?;
            if (i as usize) < rs.len() {
                Ok(rs.get(i as usize).raw())
            } else {
                Err(BuildError::new(format!("the op has no result {i}")))
            }
        })
    }
}

/// The op whose result `v` is.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_value_op(fb: *mut FirBuilder, v: FirValue) -> FirOp {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let v = fir::ValueId::from_raw(v);
            if v.index() >= f.body().num_values() {
                return Err(BuildError::new(format!("value {} does not exist", v.raw())));
            }
            match f.body().def(v) {
                ValueDef::Result { op, .. } => Ok(op.raw()),
                ValueDef::Param { .. } => Err(BuildError::new("the value is a parameter")),
            }
        })
    }
}

/// Region `i` of an op.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_op_region(fb: *mut FirBuilder, op: FirOp, i: u32) -> FirRegion {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            Ok(f.region(OpId::from_raw(op), i as usize)?.raw())
        })
    }
}

/// Parameter `i` of a region or block.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_region_param(fb: *mut FirBuilder, r: FirRegion, i: u32) -> FirValue {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let ps = f.region_params(RegionId::from_raw(r))?;
            if (i as usize) < ps.len() {
                Ok(ps.get(i as usize).raw())
            } else {
                Err(BuildError::new(format!("the region has no parameter {i}")))
            }
        })
    }
}

/// Put the next ops at the end of a region or block.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_position_at_end(fb: *mut FirBuilder, r: FirRegion) -> FirStatus {
    unsafe { builder_status(fb, |f| f.position_at_end(RegionId::from_raw(r))) }
}

/// Put the next ops right before an op.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_position_before(fb: *mut FirBuilder, op: FirOp) -> FirStatus {
    unsafe { builder_status(fb, |f| f.position_before(OpId::from_raw(op))) }
}

/// A new block of the `cf.blocks` op `op`, labeled `label` (null or empty: its id) and with
/// these parameter types. The first block made is the entry, without parameters. Blocks are
/// given to the op in the order made, by `fir_blocks_end` or when the function ends.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_block_new(
    fb: *mut FirBuilder,
    op: FirOp,
    label: *const c_char,
    params: *const FirType,
    nparams: usize,
) -> FirRegion {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let label = if label.is_null() { "" } else { cstr(label)? };
            let ps = tys(params, nparams)?;
            Ok(f.block(OpId::from_raw(op), label, &ps)?.raw())
        })
    }
}

/// Give a `cf.blocks` op the blocks made for it; no more can be added.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_blocks_end(fb: *mut FirBuilder, op: FirOp) -> FirStatus {
    unsafe { builder_status(fb, |f| f.end_blocks(OpId::from_raw(op))) }
}

/// The source location the next ops get, `@line:col`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_set_loc(fb: *mut FirBuilder, line: u32, col: u32) -> FirStatus {
    unsafe {
        builder_status(fb, |f| {
            f.set_loc(Some(fir::Loc { line, col }));
            Ok(())
        })
    }
}

/// The next ops get no location.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_clear_loc(fb: *mut FirBuilder) -> FirStatus {
    unsafe {
        builder_status(fb, |f| {
            f.set_loc(None);
            Ok(())
        })
    }
}

/// The source file of the function's locations (`loc "main.c"`); null for none.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_set_file(fb: *mut FirBuilder, file: *const c_char) -> FirStatus {
    unsafe {
        builder_status(fb, |f| {
            let file = if file.is_null() {
                None
            } else {
                Some(cstr(file)?)
            };
            f.set_file(file);
            Ok(())
        })
    }
}

/// Name a value, as `%name` in text. Unnamed values are named after their ids.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_value_set_name(
    fb: *mut FirBuilder,
    v: FirValue,
    name: *const c_char,
) -> FirStatus {
    unsafe { builder_status(fb, |f| f.name(fir::ValueId::from_raw(v), cstr(name)?)) }
}

/// Put these facts on a value, replacing any it has.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_value_set_facts(
    fb: *mut FirBuilder,
    v: FirValue,
    facts: *const FirFact,
    nfacts: usize,
) -> FirStatus {
    unsafe {
        builder_status(fb, |f| {
            let mut fs = Vec::new();
            for x in list(facts, nfacts) {
                let fact = match x.kind {
                    FIR_FACT_RANGE_S => FactArg::RangeS(x.lo.into(), x.hi.into()),
                    FIR_FACT_RANGE_U => FactArg::RangeU(x.lo.into(), x.hi.into()),
                    FIR_FACT_NONNULL => FactArg::NonNull,
                    FIR_FACT_ALIGN => FactArg::Align(x.lo as u64),
                    FIR_FACT_NOALIAS => FactArg::NoAlias,
                    FIR_FACT_READONLY => FactArg::ReadOnly,
                    k => return Err(BuildError::new(format!("{k} is not a FirFactKind"))),
                };
                fs.push((fact, Trust::from_c(x.trust)?));
            }
            f.set_facts(fir::ValueId::from_raw(v), &fs)
        })
    }
}

/// A hole `?name: ty`, usable as an operand.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_hole(
    fb: *mut FirBuilder,
    name: *const c_char,
    ty_: FirType,
) -> FirValue {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            Ok(f.hole(cstr(name)?, ty(ty_)?)?.raw())
        })
    }
}

/// `int.const` with the constant in decimal, for constants wider than 64 bits.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn fir_int_const_dec(
    fb: *mut FirBuilder,
    result: FirType,
    digits: *const c_char,
) -> FirValue {
    unsafe {
        with_builder(fb, FIR_INVALID, |f| {
            let s = cstr(digits)?;
            let Some(n) = fir::interp::parse_int(s) else {
                return Err(BuildError::new(format!("'{s}' is not an integer")));
            };
            Ok(f.int_const(ty(result)?, IntImm::from(n))?.raw())
        })
    }
}
